//! EBCDIC code pages (CCSIDs) and conversion to and from Unicode.
//!
//! CCSID 037 is the default. The Japanese mixed code pages 930 (Katakana
//! and Kanji), 939 (Latin and Kanji), 1390 and 1399 (their extended
//! versions) come from ICU's mapping tables (`codepages/`, generated by
//! tools/icu-codepages.sh): a single-byte part per code page and a
//! double-byte part per family. Mixed data shifts to double-byte
//! characters with SO (X'0E') and back with SI (X'0F'); DBCS data (PIC G,
//! DISPLAY-1) has double-byte characters only.
//!
//! The active code page of the process is `ZEUS_CCSID` (or what a tool
//! sets with `set_active` before the first conversion).

use std::collections::HashMap;
use std::sync::OnceLock;

/// Shift out (to double-byte characters) and shift in.
pub const SO: u8 = 0x0E;
pub const SI: u8 = 0x0F;
/// The double-byte space.
pub const DBCS_SPACE: [u8; 2] = [0x40, 0x40];

/// A code page: how EBCDIC bytes map to Unicode and back.
pub struct CodePage {
    pub ccsid: u32,
    /// Single byte -> Unicode (None: not mapped).
    sbcs: [Option<char>; 256],
    /// Double-byte code -> Unicode (one or two code points).
    dbcs: HashMap<u16, Vec<char>>,
    /// Unicode (one or two code points) -> EBCDIC (one or two bytes).
    to_ebcdic: HashMap<Vec<char>, Vec<u8>>,
    /// Single-byte and double-byte substitution characters.
    subchar1: u8,
    subchar: [u8; 2],
}

const TABLES: [(u32, &str, &str); 4] = [
    (
        930,
        include_str!("../codepages/ibm-930.sbcs"),
        include_str!("../codepages/ibm-300.dbcs"),
    ),
    (
        939,
        include_str!("../codepages/ibm-939.sbcs"),
        include_str!("../codepages/ibm-300.dbcs"),
    ),
    (
        1390,
        include_str!("../codepages/ibm-1390.sbcs"),
        include_str!("../codepages/ibm-16684.dbcs"),
    ),
    (
        1399,
        include_str!("../codepages/ibm-1399.sbcs"),
        include_str!("../codepages/ibm-16684.dbcs"),
    ),
];

/// The CCSIDs Zeus converts.
pub const CCSIDS: [u32; 5] = [37, 930, 939, 1390, 1399];

impl CodePage {
    fn cp037() -> CodePage {
        let mut sbcs = [None; 256];
        let mut to_ebcdic = HashMap::new();
        for b in 0..=255u8 {
            let c = char::from(crate::ebcdic::to_latin1(b));
            sbcs[b as usize] = Some(c);
            to_ebcdic.insert(vec![c], vec![b]);
        }
        CodePage {
            ccsid: 37,
            sbcs,
            dbcs: HashMap::new(),
            to_ebcdic,
            subchar1: 0x3F,
            subchar: [0xFE, 0xFE],
        }
    }

    /// A code page from its tables (lines `K EBCDIC UNICODE`, ICU's
    /// precision K: 0 round trip, 1 to EBCDIC only, 2 to the substitution
    /// character, 3 to Unicode only).
    fn from_tables(ccsid: u32, sbcs_text: &str, dbcs_text: &str) -> CodePage {
        let mut cp = CodePage {
            ccsid,
            sbcs: [None; 256],
            dbcs: HashMap::new(),
            to_ebcdic: HashMap::new(),
            subchar1: 0x3F,
            subchar: [0xFE, 0xFE],
        };
        // round trips first, so that they win over fallbacks to EBCDIC
        let mut fallbacks = Vec::new();
        for line in sbcs_text.lines().chain(dbcs_text.lines()) {
            let mut f = line.split_whitespace();
            let (Some(k), Some(e), Some(u)) = (f.next(), f.next(), f.next()) else {
                continue;
            };
            if k.starts_with('#') {
                continue;
            }
            let bytes: Vec<u8> = (0..e.len() / 2)
                .filter_map(|i| u8::from_str_radix(&e[2 * i..2 * i + 2], 16).ok())
                .collect();
            let chars: Vec<char> = u
                .split('+')
                .filter_map(|x| u32::from_str_radix(x, 16).ok())
                .filter_map(char::from_u32)
                .collect();
            if matches!(k, "0" | "3") {
                match bytes.as_slice() {
                    [b] => {
                        cp.sbcs[*b as usize] = chars.first().copied().filter(|_| chars.len() == 1)
                    }
                    [a, b] => {
                        cp.dbcs.insert(u16::from_be_bytes([*a, *b]), chars.clone());
                    }
                    _ => {}
                }
            }
            match k {
                "0" => {
                    cp.to_ebcdic.insert(chars, bytes);
                }
                "1" | "2" => fallbacks.push((chars, bytes)),
                _ => {}
            }
        }
        for (c, b) in fallbacks {
            cp.to_ebcdic.entry(c).or_insert(b);
        }
        cp
    }

    /// Whether the code page has double-byte characters (mixed data).
    pub fn is_mixed(&self) -> bool {
        !self.dbcs.is_empty()
    }

    fn sbcs_char(&self, b: u8) -> char {
        self.sbcs[b as usize].unwrap_or('\u{1A}')
    }

    fn dbcs_chars(&self, a: u8, b: u8, out: &mut String) {
        match self.dbcs.get(&u16::from_be_bytes([a, b])) {
            Some(cs) => out.extend(cs),
            None => out.push('\u{FFFD}'),
        }
    }

    /// Mixed EBCDIC data (SO and SI shift between single-byte and
    /// double-byte characters) as text.
    pub fn decode(&self, bytes: &[u8]) -> String {
        let mut out = String::with_capacity(bytes.len());
        let mut dbcs = false;
        let mut i = 0;
        while i < bytes.len() {
            let b = bytes[i];
            if self.is_mixed() && b == SO {
                dbcs = true;
            } else if self.is_mixed() && b == SI {
                dbcs = false;
            } else if dbcs && i + 1 < bytes.len() && bytes[i + 1] != SI {
                self.dbcs_chars(b, bytes[i + 1], &mut out);
                i += 1;
            } else {
                out.push(self.sbcs_char(b));
            }
            i += 1;
        }
        out
    }

    /// DBCS data (double-byte characters only, as in PIC G items) as text.
    pub fn decode_dbcs(&self, bytes: &[u8]) -> String {
        let mut out = String::with_capacity(bytes.len());
        for pair in bytes.chunks(2) {
            match pair {
                [a, b] => self.dbcs_chars(*a, *b, &mut out),
                [a] => out.push(self.sbcs_char(*a)),
                _ => {}
            }
        }
        out
    }

    /// The EBCDIC of the character(s) at the start of `cs`, and how many
    /// characters it took (two for a combining sequence).
    fn lookup(&self, cs: &[char]) -> (Option<&[u8]>, usize) {
        if cs.len() >= 2
            && let Some(b) = self.to_ebcdic.get(&cs[..2])
        {
            return (Some(b), 2);
        }
        (self.to_ebcdic.get(&cs[..1]).map(Vec::as_slice), 1)
    }

    /// Text as mixed EBCDIC data: double-byte characters between SO and SI.
    pub fn encode(&self, s: &str) -> Vec<u8> {
        let cs: Vec<char> = s.chars().collect();
        let mut out = Vec::with_capacity(cs.len());
        let mut dbcs = false;
        let mut i = 0;
        while i < cs.len() {
            let (b, n) = self.lookup(&cs[i..]);
            let b = b.unwrap_or_else(|| {
                if self.is_mixed() && !cs[i].is_ascii() && (cs[i] as u32) > 0xFF {
                    &self.subchar
                } else {
                    std::slice::from_ref(&self.subchar1)
                }
            });
            match (b.len() == 2, dbcs) {
                (true, false) => out.push(SO),
                (false, true) => out.push(SI),
                _ => {}
            }
            dbcs = b.len() == 2;
            out.extend_from_slice(b);
            i += n;
        }
        if dbcs {
            out.push(SI);
        }
        out
    }

    /// Text as DBCS data (double-byte characters only): characters with a
    /// single-byte code take their full-width double-byte form.
    pub fn encode_dbcs(&self, s: &str) -> Vec<u8> {
        let cs: Vec<char> = s.chars().collect();
        let mut out = Vec::with_capacity(cs.len() * 2);
        let mut i = 0;
        while i < cs.len() {
            let (b, n) = self.lookup(&cs[i..]);
            match b {
                Some(b) if b.len() == 2 => out.extend_from_slice(b),
                _ => {
                    let wide = match cs[i] {
                        ' ' => Some('\u{3000}'),
                        c @ '!'..='~' => char::from_u32(c as u32 + 0xFEE0),
                        _ => None,
                    };
                    match wide.and_then(|w| self.to_ebcdic.get(&vec![w])) {
                        Some(b) if b.len() == 2 => out.extend_from_slice(b),
                        _ => out.extend_from_slice(&self.subchar),
                    }
                }
            }
            i += n;
        }
        out
    }
}

/// The code page of a CCSID (None if Zeus does not convert it).
pub fn get(ccsid: u32) -> Option<&'static CodePage> {
    static PAGES: OnceLock<Vec<CodePage>> = OnceLock::new();
    let pages = PAGES.get_or_init(|| {
        let mut v = vec![CodePage::cp037()];
        v.extend(
            TABLES
                .iter()
                .map(|(c, s, d)| CodePage::from_tables(*c, s, d)),
        );
        v
    });
    pages.iter().find(|p| p.ccsid == ccsid)
}

static ACTIVE: OnceLock<u32> = OnceLock::new();

/// Sets the active code page (before the first conversion); false if the
/// CCSID is not supported or the code page was already chosen.
pub fn set_active(ccsid: u32) -> bool {
    get(ccsid).is_some() && ACTIVE.set(ccsid).is_ok()
}

/// The active code page: `set_active`, else `ZEUS_CCSID`, else 037.
pub fn active() -> &'static CodePage {
    let ccsid = *ACTIVE.get_or_init(|| {
        std::env::var("ZEUS_CCSID")
            .ok()
            .and_then(|v| v.trim().parse().ok())
            .filter(|c| get(*c).is_some())
            .unwrap_or(37)
    });
    get(ccsid).expect("supported CCSID")
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn mixed_japanese() {
        for ccsid in [930, 939, 1390, 1399] {
            let cp = get(ccsid).unwrap();
            let text = "ABC 日本語テキスト 123";
            let e = cp.encode(text);
            assert_eq!(cp.decode(&e), text, "{ccsid}");
            // SO and SI around the double-byte run, one pair
            assert_eq!(e.iter().filter(|&&b| b == SO).count(), 1);
            assert_eq!(e.iter().filter(|&&b| b == SI).count(), 1);
            assert_eq!(&e[..4], &[0xC1, 0xC2, 0xC3, 0x40]);
        }
        let cp = get(939).unwrap();
        // 日 is X'4562' in the double-byte part of 930 / 939 (CCSID 300)
        assert_eq!(cp.encode("日"), [SO, 0x45, 0x62, SI]);
        // half-width katakana are single-byte characters in 930
        let k = get(930).unwrap();
        let e = k.encode("ｱｲｳ");
        assert_eq!(e.len(), 3);
        assert_eq!(k.decode(&e), "ｱｲｳ");
        // lower-case Latin letters are single-byte in 939 (Latin), but
        // not in 930 (Katakana), where they become double-byte
        assert!(!cp.encode("abc").contains(&SO));
        assert_eq!(k.decode(&k.encode("abc")), "abc");
    }

    #[test]
    fn dbcs_data() {
        let cp = get(1399).unwrap();
        let e = cp.encode_dbcs("漢字 AB");
        assert_eq!(e.len(), 10);
        assert_eq!(cp.decode_dbcs(&e), "漢字\u{3000}ＡＢ");
        assert_eq!(cp.decode_dbcs(&DBCS_SPACE), "\u{3000}");
        // a character outside the BMP and a combining sequence in 1390/1399
        let s = "\u{2A6B2}\u{00E6}\u{0300}";
        assert_eq!(cp.decode(&cp.encode(s)), s);
    }

    #[test]
    fn substitution_and_037() {
        let cp = get(939).unwrap();
        // unmapped: the substitution characters (double-byte for
        // characters beyond Latin-1)
        assert_eq!(cp.encode("\u{0E3F}"), [SO, 0xFE, 0xFE, SI]);
        assert_eq!(get(930).unwrap().encode("\u{00A0}"), [0x3F]);
        assert_eq!(cp.decode(&[SO, 0xFE, 0xFE, SI]), "\u{FFFD}");
        let us = get(37).unwrap();
        assert_eq!(us.encode("A1é"), [0xC1, 0xF1, 0x51]);
        assert_eq!(us.decode(&[0xC1, 0x0E, 0x51]), "A\u{e}é");
    }
}
